            object? argument0,
            object? argument1,
            object? argument2) => string.Format(resourceFormat, argument0, argument1, argument2);

        internal static string Format(string resourceFormat, params object?[]? arguments) =>
            arguments is null ? resourceFormat : string.Format(resourceFormat, arguments);
    }
}
